@if ($assistantVisible)
<div x-data="tpzAssistant()" x-init="init()" class="tpz-ai-root" wire:ignore>
    <button x-show="!open" @click="open=true; load()" class="tpz-ai-launcher" aria-label="Open TPZ AI Assistant"><span aria-hidden="true">✦</span><span>TPZ AI</span></button>
    <section x-cloak x-show="open" :class="{'tpz-ai-full':full}" class="tpz-ai-panel" role="dialog" aria-label="TPZ AI Assistant">
        <header class="tpz-ai-header"><div class="tpz-ai-brand"><span class="tpz-ai-mark" aria-hidden="true">✦</span><span><strong>TPZ Assistant</strong><small x-text="provider === 'mock' ? 'Demo mode · Read-only ERP data' : (available ? 'Connected to authorized ERP data' : 'OpenAI unavailable · API key not configured')"></small></span></div><div class="tpz-ai-controls"><button @click="newChat()" title="New chat" aria-label="New chat">＋</button><button @click="full=!full" :title="full?'Restore window':'Expand to full screen'" aria-label="Expand or restore">□</button><button @click="open=false" title="Minimize" aria-label="Minimize">−</button><button @click="close()" title="Close" aria-label="Close">×</button></div></header>
        <div class="tpz-ai-toolbar"><button class="tpz-ai-sidebar-toggle" @click="historyOpen=!historyOpen" :aria-expanded="historyOpen">☰ <span>History</span></button><span class="tpz-ai-demo" x-show="provider==='mock'">MOCK DEMONSTRATION</span><button @click="newChat()">＋ New chat</button></div>
        <div class="tpz-ai-layout" :class="{'tpz-ai-expanded':full,'history-hidden':!historyOpen}">
            <aside class="tpz-ai-history" aria-label="Conversation history"><template x-for="item in conversations" :key="item.id"><div class="tpz-ai-history-row"><button @click="select(item.id)" :class="{'active':item.id===conversationId}" x-text="item.title"></button><button class="tpz-ai-rename" @click="rename(item)" title="Rename conversation" aria-label="Rename conversation">✎</button><button class="tpz-ai-delete" @click="deleteChat(item.id)" title="Delete conversation" aria-label="Delete conversation">×</button></div></template><p x-show="conversations.length===0" class="tpz-ai-empty-history">Your conversations will appear here.</p></aside>
            <div class="tpz-ai-main"><div class="tpz-ai-messages" x-ref="messages" aria-live="polite">
                <template x-if="messages.length===0"><div class="tpz-ai-welcome"><div class="sparkle">✦</div><strong>How can I help with your ERP?</strong><p>Answers use authorized TPZ reports. Demonstration mode is labelled.</p><div class="tpz-ai-suggestions"><button @click="suggest('What are today’s sales orders?')">Today’s orders</button><button @click="suggest('Show current product inventory')">Inventory</button><button @click="suggest('Show customer returns awaiting QC')">Returns awaiting QC</button><button @click="suggest('Show pending stock requests')">Pending requests</button></div></div></template>
                <template x-for="message in messages" :key="message.id || message.localId"><article :class="message.role==='user'?'user':'assistant'" class="tpz-ai-bubble"><div class="tpz-ai-avatar" x-text="message.role==='user'?'You':'✦'"></div><div class="tpz-ai-message-content" x-html="message.role==='assistant'?safeMarkdown(message.content):escapeHtml(message.content)"></div><div class="tpz-ai-message-actions"><small x-show="message.status==='interrupted'">Generation stopped · partial answer</small><small x-show="message.status==='streaming'" x-text="stageMessage"></small><button x-show="message.role==='assistant' && (message.status==='complete'||message.status==='interrupted')" @click="copy(message.content)">Copy</button><button x-show="message.status==='failed'" @click="retry()">Retry</button></div></article></template>
                <div x-show="busy && !hasAssistantText()" class="tpz-ai-progress"><i></i><span x-text="stageMessage || 'Preparing your response…'"></span></div><div x-show="error" class="tpz-ai-error" role="alert" x-text="error"></div>
            </div><div x-show="links.length" class="tpz-ai-links"><template x-for="link in links" :key="link.url"><a :href="link.url" x-text="link.label"></a></template></div><form class="tpz-ai-composer" @submit.prevent="send()"><textarea x-ref="input" x-model="draft" @keydown.enter="onEnter($event)" placeholder="Message TPZ Assistant…" rows="1" maxlength="6000" aria-label="Message TPZ Assistant"></textarea><button x-show="!busy" type="submit" :disabled="!draft.trim()" aria-label="Send message">➤</button><button x-show="busy" type="button" class="tpz-ai-stop" @click="stop()" aria-label="Stop generation">■</button></form><small class="tpz-ai-foot">Read-only · ERP permissions apply · Verify important figures</small></div>
        </div>
    </section>
</div>
<script>
function tpzEscapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function tpzSafeMarkdown(value){const escaped=tpzEscapeHtml(value);const inline=s=>s.replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>');const lines=escaped.split(/\r?\n/);let out='',list=null,table=false;const close=()=>{if(list){out+=list==='ul'?'</ul>':'</ol>';list=null}if(table){out+='</tbody></table>';table=false}};for(const line of lines){const trimmed=line.trim();if(!trimmed){close();continue}const heading=trimmed.match(/^(#{1,3})\s+(.+)$/);if(heading){close();const level=heading[1].length;out+=`<h${level}>${inline(heading[2])}</h${level}>`;continue}if(/^\|.*\|$/.test(trimmed)){const cells=trimmed.slice(1,-1).split('|').map(x=>x.trim());if(cells.every(x=>/^:?-{3,}:?$/.test(x)))continue;if(!table){close();out+='<table><tbody>';table=true}out+='<tr>'+cells.map(x=>`<td>${inline(x)}</td>`).join('')+'</tr>';continue}const bullet=trimmed.match(/^[-*]\s+(.+)$/),number=trimmed.match(/^\d+\.\s+(.+)$/);if(bullet||number){const kind=bullet?'ul':'ol';if(list!==kind){close();list=kind;out+=`<${kind}>`}out+=`<li>${inline((bullet||number)[1])}</li>`;continue}close();out+=`<p>${inline(trimmed)}</p>`}close();return out}
function tpzAssistant(){return {open:false,full:false,historyOpen:true,busy:false,error:'',draft:'',provider:'mock',available:true,conversationId:null,conversations:[],messages:[],links:[],lastPrompt:'',stageMessage:'',controller:null,requestStarted:0,firstDeltaAt:null,init(){},escapeHtml:tpzEscapeHtml,safeMarkdown:tpzSafeMarkdown,async load(){try{const r=await fetch('/admin/ai-assistant',{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const d=await r.json();this.conversations=d.conversations;this.links=d.links||[];this.provider=d.settings.provider;this.available=d.settings.available;if(!this.available)this.error='OpenAI is unavailable because the server API key is not configured.';if(!this.conversationId&&this.conversations.length)await this.select(this.conversations[0].id);else if(!this.conversationId)await this.newChat()}catch(e){this.error='Assistant is unavailable. Please refresh or try again.'}},headers(){return {Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''}},async list(){const r=await fetch('/admin/ai-assistant',{headers:{Accept:'application/json'}});if(r.ok){const d=await r.json();this.conversations=d.conversations;this.links=d.links||[]}},async newChat(){const r=await fetch('/admin/ai-assistant/conversations',{method:'POST',headers:this.headers()});if(!r.ok){this.error='Could not start a new chat.';return}this.conversationId=(await r.json()).conversation.id;this.messages=[];this.error=this.available?'':'OpenAI is unavailable because the server API key is not configured.';await this.list();this.$nextTick(()=>this.$refs.input?.focus())},async rename(item){const title=prompt('Rename conversation',item.title);if(title===null||!title.trim())return;const r=await fetch('/admin/ai-assistant/conversations/'+item.id,{method:'PATCH',headers:this.headers(),body:JSON.stringify({title:title.trim()})});if(!r.ok){this.error='Could not rename the conversation.';return}const d=await r.json();item.title=d.conversation.title},async deleteChat(id){if(!confirm('Delete this conversation and its messages?'))return;const r=await fetch('/admin/ai-assistant/conversations/'+id,{method:'DELETE',headers:this.headers()});if(!r.ok){this.error='Could not delete the conversation.';return}if(this.conversationId===id){this.conversationId=null;this.messages=[]}await this.list()},async close(){if(this.busy)this.stop();this.open=false;this.full=false},async select(id){this.conversationId=id;this.error='';const r=await fetch('/admin/ai-assistant/conversations/'+id,{headers:{Accept:'application/json'}});if(!r.ok){this.error='Conversation could not be loaded.';return}this.messages=(await r.json()).messages;this.scroll()},async suggest(text){this.draft=text;await this.send()},onEnter(event){if(!event.shiftKey){event.preventDefault();this.send()}},hasAssistantText(){return this.messages.some(m=>m.role==='assistant'&&m.content)},async send(retry=false){if(this.busy)return;if(!retry){this.lastPrompt=this.draft.trim();if(!this.lastPrompt)return;this.messages.push({role:'user',content:this.lastPrompt,localId:Date.now()});this.draft=''}this.error='';this.stageMessage='Understanding your question…';const item={role:'assistant',content:'',status:'streaming',localId:Date.now()+1};this.messages.push(item);this.busy=true;this.controller=new AbortController();this.requestStarted=performance.now();this.firstDeltaAt=null;this.scroll();try{const response=await fetch('/admin/ai-assistant/conversations/'+this.conversationId+'/messages',{method:'POST',headers:this.headers(),body:JSON.stringify({message:this.lastPrompt}),signal:this.controller.signal});if(!response.ok)throw Error();const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const parts=buffer.split('\n\n');buffer=parts.pop();for(const part of parts){const line=part.split('\n').find(x=>x.startsWith('data: '));if(!line)continue;const event=JSON.parse(line.slice(6));if(event.type==='delta'){if(this.firstDeltaAt===null)this.firstDeltaAt=performance.now();item.content+=event.text;this.scroll()}if(event.type==='stage')this.stageMessage=event.message;if(event.type==='done'){item.status='complete';item.id=event.message_id;item.metrics=event.metrics;item.clientMetrics={requestStartToFirstTokenMs:this.firstDeltaAt===null?null:Math.round(this.firstDeltaAt-this.requestStarted),totalClientMs:Math.round(performance.now()-this.requestStarted)}}if(event.type==='error'){this.error=event.message;throw Error()}}}if(item.status==='streaming')throw Error();await this.list()}catch(e){if(e.name==='AbortError'){item.status='interrupted';this.error='Generation stopped. Any partial text is kept; budget usage remains reserved if the provider may have processed it.'}else{item.status=item.content?'interrupted':'failed';if(!this.error)this.error='The response was interrupted. Retry when ready.'}}finally{this.busy=false;this.controller=null;this.scroll()}},stop(){if(this.controller)this.controller.abort()},async retry(){const last=this.messages.at(-1);if(last?.role==='assistant'&&last.status==='failed'){this.messages.pop();await this.send(true)}},async copy(text){try{await navigator.clipboard.writeText(text)}catch(e){this.error='Could not copy this response.'}},scroll(){this.$nextTick(()=>{const el=this.$refs.messages;if(el)el.scrollTop=el.scrollHeight})}}}
</script>
@endif
